receiveMessage({ name, data }) {
  const browser = this.browsingContext?.top.embedderElement;
  if (!browser) {
    return;
  }
  const group = browser.getAttribute("messagemanagergroup");

case "openLinkInNewTab":
  openLinkInNewTab(data.href, {
    initialBrowsingContextGroupId: browser.getAttribute(
      "initialBrowsingContextGroupId"
    ),
    linkHandler: group || "browsers",
    userContextId: this.browsingContext.originAttributes.userContextId,
    triggeringPrincipal: this.manager.documentPrincipal,
    csp: browser.csp,
  });

/**
 * Opens the given url in a new tab in the most recent mail window. All provided
 * parameters are passed into openTab(), if any.
 *
 * @param {string} url
 * @param {object} [params]
 */
export function openLinkInNewTab(url, params = {}) {
  const mailWindow = Services.wm.getMostRecentWindow("mail:3pane");
  if (mailWindow) {
    mailWindow.focus();
    mailWindow.document
      .getElementById("tabmail")
      .openTab("contentTab", { url, ...params });
  }
}
